package com.yeyamo_mobile.api.booking_service.infrastructure.messaging;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.booking_service.application.BookingApplicationService;
class PaymentEventConsumerTest{@Test void consumesAuthorizationOnlyOnce()throws Exception{var service=mock(BookingApplicationService.class);var processed=mock(ProcessedEventRepository.class);when(processed.existsById(any())).thenReturn(false,true);var consumer=new PaymentEventConsumer(new ObjectMapper(),service,processed);String raw="{\"eventId\":\"11111111-1111-1111-1111-111111111111\",\"eventType\":\"payment.authorized\",\"eventVersion\":1,\"payload\":{\"sourceType\":\"BOOKING\",\"sourceId\":\"22222222-2222-2222-2222-222222222222\",\"paymentId\":\"pay-1\"}}";consumer.consume(raw);consumer.consume(raw);verify(service).paymentAuthorized(any(),any(),eq("pay-1"),isNull());verify(processed).save(any());}@Test void ignoresCommercePaymentEvent()throws Exception{var service=mock(BookingApplicationService.class);var processed=mock(ProcessedEventRepository.class);var consumer=new PaymentEventConsumer(new ObjectMapper(),service,processed);consumer.consume("{\"eventId\":\"11111111-1111-1111-1111-111111111111\",\"eventType\":\"payment.authorized\",\"eventVersion\":1,\"payload\":{\"sourceType\":\"COMMERCE_ORDER\",\"sourceId\":\"22222222-2222-2222-2222-222222222222\",\"paymentId\":\"pay-1\"}}");verifyNoInteractions(service);verify(processed).save(any());}}
